<?php
 namespace QQWorld\Framework\ObjectManager\Test\Unit\Code\Generator; use Composer\Autoload\ClassLoader; use QQWorld\Framework\Code\Generator\Io; use QQWorld\Framework\ObjectManager\Code\Generator\Repository; use \PHPUnit_Framework_MockObject_MockObject as MockObject; class GenerateRepositoryTest extends \PHPUnit\Framework\TestCase { private $ioGenerator; protected function setUp() { $this->ioGenerator = $this->getMockBuilder(Io::class) ->disableOriginalConstructor() ->getMock(); $loader = new ClassLoader(); $loader->addPsr4( 'QQWorld\\Framework\\ObjectManager\\Code\\Generator\\', __DIR__ . '/_files' ); $loader->register(); } public function testGenerate($className, $sourceClassName, $fileName) { $repository = $this->getMockBuilder(Repository::class) ->setMethods(['_validateData']) ->setConstructorArgs([ $sourceClassName, null, $this->ioGenerator ]) ->getMock(); $this->ioGenerator ->method('generateResultFileName') ->with('\\' . $className) ->willReturn($fileName . '.php'); $repositoryCode = file_get_contents(__DIR__ . '/_files/' . $fileName . '.txt'); $this->ioGenerator->method('writeResultFile') ->with($fileName . '.php', $repositoryCode); $repository->method('_validateData') ->willReturn(true); $generated = $repository->generate(); $this->assertEquals($fileName . '.php', $generated, 'Generated repository is invalid.'); } public function interfaceListDataProvider() { return [ [ \QQWorld\Framework\ObjectManager\Code\Generator\SampleRepository::class, \QQWorld\Framework\ObjectManager\Code\Generator\Sample::class, 'SampleRepository' ], [ \QQWorld\Framework\ObjectManager\Code\Generator\TSampleRepository::class, \QQWorld\Framework\ObjectManager\Code\Generator\TSample::class, 'TSampleRepository' ], ]; } public function testValidateData() { $sourceClassName = 'QQWorld_Module_Controller_Index'; $resultClassName = 'QQWorld_Module_Controller'; $repository = new Repository(); $repository->init($sourceClassName, $resultClassName); $this->assertFalse($repository->generate()); }